rust_translation:
fn add_template_metadata(component: &mut Component, templates: HashMap<String, Template>) {
    component.templates = templates.clone();

    // Add template bindings to track which state affects which templates
    component.template_bindings = HashMap::new();

    for (path, template) in &templates {
        for binding in &template.bindings {
            component.template_bindings
                .entry(binding.clone())
                .or_insert_with(Vec::new)
                .push(path.clone());
        }
    }
}
